package com.panaderia.service;
import com.panaderia.dao.ProductoDAO; import com.panaderia.model.Producto; import java.sql.SQLException; import java.util.List;
public class ProductoService { private final ProductoDAO dao=new ProductoDAO(); public List<Producto> listarTodos()throws SQLException{return dao.listarTodos();} public String guardar(Producto p)throws SQLException{validar(p);if(p.getId()<=0){int id=dao.insertar(p);p.setId(id);return "Producto registrado correctamente (ID "+id+").";}if(!dao.actualizar(p))throw new SQLException("No se pudo actualizar el producto.");return "Producto actualizado correctamente.";} public String eliminar(int id)throws SQLException{if(id<=0)throw new IllegalArgumentException("Seleccione un producto.");if(!dao.eliminar(id))throw new SQLException("No se encontró el producto.");return "Producto eliminado correctamente.";} public Producto buscar(int id)throws SQLException{return dao.buscarPorId(id);} public String ajustarStock(int id,int cantidad,boolean entrada)throws SQLException{if(id<=0)throw new IllegalArgumentException("Seleccione un producto.");if(cantidad<=0)throw new IllegalArgumentException("La cantidad debe ser mayor a 0.");Producto p=dao.buscarPorId(id);if(p==null)throw new SQLException("Producto no encontrado.");int n=entrada?p.getStock()+cantidad:p.getStock()-cantidad;if(n<0)throw new IllegalArgumentException("Stock insuficiente. Disponible: "+p.getStock()+".");if(!dao.actualizarStock(id,n))throw new SQLException("No se pudo actualizar el stock.");return (entrada?"Entrada":"Salida")+" registrada. Nuevo stock: "+n+".";} private void validar(Producto p){if(p.getNombre()==null||p.getNombre().trim().isEmpty())throw new IllegalArgumentException("El nombre del producto es obligatorio.");if(p.getCategoria()==null||p.getCategoria().trim().isEmpty())throw new IllegalArgumentException("Seleccione una categoría.");if(p.getPrecio()<=0)throw new IllegalArgumentException("El precio debe ser mayor a 0.");if(p.getStock()<0)throw new IllegalArgumentException("El stock no puede ser negativo.");if(p.getStockMinimo()<0)throw new IllegalArgumentException("El stock mínimo no puede ser negativo.");}}
